const rows=csv.trim().split(/\r?\n/).slice(1).map(l=>{const [timestamp,total]=l.split(',');return {date:timestamp.slice(0,10),hour:+timestamp.slice(11,13),weekday:new Date(timestamp.slice(0,10)+'T12:00:00+08:00').getUTCDay(),total:+total};});
const night=r.anomaly.findings.find(f=>f.id==='night_waste'),weekday=rows.filter(x=>x.weekday>0&&x.weekday<6),after=weekday.filter(x=>x.hour<8||x.hour>18).map(x=>x.total).sort((a,b)=>a-b),pos=(after.length-1)*.1,baseline=after[Math.floor(pos)]+(after[Math.ceil(pos)]-after[Math.floor(pos)])*(pos%1);
const hours=Array.from({length:24},(_,h)=>{const a=weekday.filter(x=>x.date>=night.start_date&&x.hour===h);return a.reduce((s,x)=>s+x.total,0)/a.length;});
const smooth=points=>points.map(([x,y],i)=>i?`C${(points[i-1][0]+x)/2} ${points[i-1][1]} ${(points[i-1][0]+x)/2} ${y} ${x} ${y}`:`M${x} ${y}`).join(' ');
const max=Math.max(...hours)*1.15,xy=hours.map((v,h)=>[25+h/23*550,210-v/max*160]),by=210-baseline/max*160;
const loadCurve=`<svg viewBox="0 0 600 270" role="img" aria-label="Average affected weekday hourly load from meter CSV"><text x="25" y="30">Hourly building use</text>${[[0,7],[19,23]].map(([a,z])=>`<path class="waste" d="${smooth(xy.slice(a,z+1))}L${xy[z][0]} ${by}H${xy[a][0]}Z"/>`).join('')}<path class="reference" d="M25 ${by}H575"/><path class="line" d="${smooth(xy)}"/><text x="25" y="240">00:00</text><text x="275" y="240">12:00</text><text x="530" y="240">23:00</text><text x="25" y="265">Night baseline ${Math.round(baseline)} kW</text></svg><p class="small">Amber: after-hours use above the baseline.</p>`;
root.customerData={hours,baseline,source:'CSV weekday hourly averages from finding onset'};
const py=v=>210-(v-.65)/.25*150;
const trend=`<svg viewBox="0 0 600 270" role="img" aria-label="Chiller efficiency across the sample month"><rect class="redzone" x="25" y="35" width="550" height="${py(plant.limit_kwrt)-35}" rx="10"/><text x="25" y="20">Energy per unit of cooling \u00b7 kW/RT</text><path class="reference" d="M25 ${py(plant.limit_kwrt)}H575"/><text x="25" y="${py(plant.limit_kwrt)-12}">Reference ${plant.limit_kwrt.toFixed(2)}</text><path class="line" d="${smooth(Object.entries(plant.kwrt_daily).map(([d,v])=>[25+(d-1)/29*550,py(v)]))}"/><text x="25" y="245">Start ${plant.kwrt_start.toFixed(2)}</text><text x="460" y="245">End ${plant.kwrt_end.toFixed(2)}</text></svg>`;
const bars=[['Office median',b.benchmarks.median],['Your example building',b.eui_kwh_m2_yr.value],['BCA office reference',b.benchmarks.mei_threshold]].map(([label,v])=>`<div class="euirow"><div>${label}<strong>${Math.round(v)}</strong></div><div class="bar" style="width:${v/b.benchmarks.mei_threshold*100}%"></div></div>`).join('');
const icon=(symbol,title,body)=>`<div class="step"><span class="icon" aria-hidden="true">${symbol}</span><h3>${title}</h3><p>${body}</p></div>`;

const cta='<a class="cta" href="/free-eui-check">Get a free energy check</a>', cost=money(r.proposal.night_waste_sgd_per_affected_night.value,10);
const mini=values=>{const lo=Math.min(...values),hi=Math.max(...values);return `<svg class="mini-chart" viewBox="0 0 300 120" role="img" aria-label="Trend from synthetic demo data"><path class="reference" d="M10 100H290"/><path class="line" d="${values.map((v,i)=>`${i?'L':'M'}${10+i/(values.length-1)*280} ${95-(v-lo)/(hi-lo||1)*75}`).join(' ')}"/><text x="10" y="110">Start</text><text x="290" y="110" text-anchor="end">End</text></svg>`;};
const saturdayChart=`<svg class="mini-chart" viewBox="0 0 300 150" role="img" aria-label="Saturday energy as a percentage of weekday energy, synthetic demo">${Object.entries(sat.saturday_vs_weekday_pct).map(([day,v],i)=>`<rect class="waste" x="${18+i*72}" y="${110-v}" width="42" height="${v}" rx="4"/><text x="${39+i*72}" y="${100-v}" text-anchor="middle">${v}%</text><text x="${39+i*72}" y="140" text-anchor="middle">Sep ${day}</text>`).join('')}</svg>`;
const content=[
['opening','cinema','After everyone leaves',`<div class="hero-copy"><h1>It's 2am.<br>Still working?</h1><p>Your energy story doesn't end at closing time.</p>${cta}</div><div class="chapter"><h2>The office is quiet.<br>Is your meter?</h2><p>Look at what happens between the hours.</p></div>`],
['question','','After hours',`<h2>Your building should sleep.<br>This one doesn't.</h2><p>A monthly bill can't show you when the waste begins.</p><div class="card feature reveal"><div class="feature-top"><div><small>Demo building \u00b7 synthetic data</small><h3>The cost of staying on.</h3></div><div class="metric">About ${cost}<span class="unit">a night</span></div></div><div class="draw">${loadCurve}</div></div>`],
['patterns','','The patterns',`<h2>Three things we catch.</h2><p>Clear signals. Useful next steps.</p><small class="example">Synthetic demo data</small><div class="grid"><div class="card reveal"><h3>Night waste</h3>${mini(hours)}<div class="metric">About ${cost}</div><p>Per affected weekday night above the expected baseline.</p></div><div class="card reveal"><h3>Saturdays like weekdays</h3>${saturdayChart}<p>Saturdays use 74\u201381% of weekday energy. Check the schedule.</p></div><div class="card reveal"><h3>Air-con working harder</h3>${mini(Object.values(plant.kwrt_daily))}<p>Your air-con plant uses more power for the same cooling. We flag it for an engineer.</p></div></div>`],
 ['benchmark','','Your energy use',`<h2>Where you stand.</h2><p>Above typical office use.<br>Just under the BCA office line.</p><div class="card feature reveal"><small>Synthetic demo \u00b7 annualised EUI</small><div class="euibars">${bars}</div><p class="small">kWh/m\u00b2/year</p></div>`],
['how','','How it works',`<h2>From export to clear report.</h2><p>A practical first step, without changing your equipment.</p><div class="grid">${[['Send your export','Share hourly meter readings and gross floor area.'],['Analyse and double-check','Find the patterns, then independently recompute the figures.'],['Get a clear report','Priorities and next steps for your team to review.']].map(([t,p],i)=>`<div class="card reveal"><span class="number">0${i+1}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div>`],
['checked','','What you get',`<h2>Clarity you can act on.</h2><p>The patterns, priorities and next steps in one readable report.</p><div class="split"><figure class="report reveal"><div class="report-preview"><small>SGnergy / September 2026</small><h3>Executive summary</h3><p>Demo Office \u00b7 Synthetic data</p><div class="report-main"><strong>160,274</strong><span>kWh this month</span></div><div class="report-main"><strong>195</strong><span>Annualised EUI \u00b7 kWh/m\u00b2/year</span></div><h4>Three priorities</h4>${r.proposal.top3_issues_sgd_year.map(x=>`<div class="report-row"><span>${x.issue.split(' (')[0]}</span><strong>${money(x.sgd_year)} / yr</strong></div>`).join('')}<p class="report-total">Potential ceiling <strong>${money(r.proposal.total_potential_savings_sgd_year)} / year</strong></p><small>Estimated from one month. Review schedules and inspect the plant.</small></div><figcaption>Summary preview \u00b7 actual sample report figures</figcaption></figure><div class="card trust reveal"><h3>Checked twice.</h3><p>Independently recomputed, then reviewed by the founder.</p><a href="/sample-report">View the report structure preview</a></div></div>`],
 ['services','','Pricing',`<h2>Start with one building.</h2><p>A clear first step. A closer look. An ongoing view.</p><div class="grid pricing">${[['Free energy check','Free','Floor area and energy use.','Get a free energy check'],['Building health check',money(c.pricing.health_check_one_off_sgd),'A focused, one-off meter review.','Book a health check'],['Monthly monitoring',money(c.pricing.monthly_monitoring_sgd_per_building),'per month \u00b7 Watch for changes over time.','Start monitoring']].map(([t,v,p,button],i)=>`<div class="card reveal">${i===1?'<span class="popular">One-off review</span>':''}<h3>${t}</h3><div class="metric">${v}</div><p>${p}</p><a class="cta" href="${i===0?'/free-eui-check':'mailto:abu.bakar.nasir.abn@gmail.com?subject='+encodeURIComponent(button)}">${button}</a></div>`).join('')}</div>`],
['resolution','cinema','A better end to the day',`<h2 class="ending-headline"><span>Same building.</span><span>Lights off when everyone leaves.</span></h2><div class="metric">Up to about ${money(r.proposal.total_potential_savings_sgd_year,1000)} per year<span class="unit">Demo annual potential ceiling, not verified savings.</span></div><a class="cta" href="/free-eui-check">Get a free energy check</a>`],
['opportunity','','The founder',`<div class="card trust reveal"><div class="founder-photo"><img ${new URL(root.dataset.assetBase).hostname.endsWith('.invalid')?'':'src="'+asset('assets/founder-studio.webp')+'"'} width="600" height="600" loading="lazy" alt="Abu Bakar Nasir"></div><h2>Built by an engineer.</h2><p>Abu Bakar Nasir. Mechanical engineer, PV-thermal researcher, turned AI developer.</p><p>I built SGnergy to turn building energy patterns into clearer questions and useful next steps.</p></div>`],
['prepare','','FAQ',`<h2>Before we start.</h2><div class="faq">${[['Is my data safe?','Use the Free EUI check form for building and contact details. Email first to agree how meter data will be shared. Review /privacy before sending sensitive information.'],['Is this a statutory audit?','No. This is a screening report, not a PEA or MEI audit. Professional judgement belongs to the appropriate engineer.'],['What do I need to send?','Start with building and contact details at /free-eui-check. For a paid review, email the hourly export and floor area after agreeing the scope. The form is not a file-upload service.']].map(([q,a],i)=>`<details><summary aria-controls="answer-${i}">${q}</summary><p id="answer-${i}">${a}</p></details>`).join('')}</div>`],
['contact','','Your building, next',`<h2>See what your building<br>does after hours.</h2><p>Start with your meter. Find the right next question.</p><a class="cta" href="/free-eui-check">Get a free energy check</a>`]
];
